import {iso} from './isometric.js';
/** Original code-native SVG, no simulation effects or external artwork. @param {number} [rotation] @param {readonly {count:number,massG:number}[]} [school] @param {{feeding?:boolean,aerator?:boolean,efficient?:boolean,biofilter?:boolean,autoFeeder?:boolean}} [options] */
export function fishPondScene(rotation=0,school=[{count:4,massG:500},{count:8,massG:30}],options={}){
 /** @param {number} x @param {number} y @param {number} w @param {number} h */
 const polygon=(x,y,w,h)=>[[x,y],[x+w,y],[x+w,y+h],[x,y+h]].map(([a,b])=>{const p=iso(a,b,rotation);return p.x+','+p.y;}).join(' ');
 /** @param {number} x @param {number} y */
 const loc=(x,y)=>iso(x,y,rotation);
 /** @param {number} x @param {number} y @param {number} massG */
 const fish=(x,y,massG)=>{const p=loc(x,y),k=massG<100?.4:massG<250?.6:massG<500?.8:1;return `<g transform="translate(${p.x} ${p.y}) scale(${k})" opacity=".85"><ellipse rx="19" ry="8" fill="#316c78"/><path d="M-16,0 l-14,-10 v20Z" fill="#4d8990"/><path d="M-8,-4 l8,-8 8,8" fill="#508a92"/><circle cx="10" cy="-2" r="2" fill="#173b49"/></g>`;};
 return `<svg data-fish-feeding="${!!options.feeding}" viewBox="75 90 750 420" role="img" aria-label="Fish pond presentation preview, not live gameplay" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="fish-preview-water" x2="0" y2="1"><stop stop-color="#9bddd4"/><stop offset="1" stop-color="#5cacae"/></linearGradient></defs><polygon points="${polygon(.1,.1,6.8,6.8)}" fill="#d2dfb4" stroke="#b8ca96" stroke-width="4"/><polygon points="${polygon(1,1,5,4)}" fill="#6d9b9a" stroke="#5e8078" stroke-width="17" stroke-linejoin="round"/><polygon data-fish-water="1" data-fish-object="pond" points="${polygon(1.05,1.05,4.9,3.9)}" fill="url(#fish-preview-water)" stroke="#dddfbd" stroke-width="7"/>${school.map((c,i)=>`<g data-fish-school="${i}" data-fish-stage="${c.massG<100?'fingerling':c.massG<250?'juvenile':c.massG<500?'grow-out':'adult'}" data-fish-count="${c.count}" data-fish-size="${c.massG>=250?'large':'small'}">${Array.from({length:Math.min(c.count,2)},(_,n)=>fish(1.9+(i%4)*1.05+n*.45,1.8+Math.floor(i/4)*.7+n*.75,c.massG)).join('')}</g>`).join('')}${options.feeding?`<g data-fish-food="true">${[[3,2],[3.3,2.2],[3.6,2.1]].map(([x,y])=>{const p=loc(x,y);return `<circle cx="${p.x}" cy="${p.y}" r="3" fill="#e8c67a"/>`;}).join('')}</g>`:''}<polygon data-fish-deck="1" data-fish-object="harvest" points="${polygon(4.7,4.8,1.4,1.3)}" fill="#d2b88a" stroke="#967d55" stroke-width="3"/>${[0,.3,.6,.9].map(n=>`<polyline points="${polygon(4.8+n,4.85,.03,1.2)}" fill="none" stroke="#af946d"/>`).join('')}${[[2,1.1],[3.1,3.8],[5.1,3.1]].map(([x,y])=>{const p=loc(x,y);return `<ellipse cx="${p.x}" cy="${p.y}" rx="31" ry="11" stroke="#d7f2e8" fill="none" opacity=".55"/>`;}).join('')}${[[1,2.6],[6,3.7]].map(([x,y],i)=>{const p=loc(x,y);return `<g data-fish-station="${i?'water':'inlet'}" ${i?'data-fish-object="water"':''} transform="translate(${p.x} ${p.y})"><path d="M0,8 v-29 h${i?-34:34}" stroke="#6e8d8c" stroke-width="9" fill="none"/><circle cy="-20" r="9" fill="#e3a35c" stroke="#7e795e" stroke-width="2"/></g>`;}).join('')}<g data-fish-object="aerator" data-fish-efficient="${!!options.efficient}" data-fish-aerator="${options.aerator?'on':'off'}" transform="translate(${loc(2.8,4.2).x} ${loc(2.8,4.2).y})"><ellipse rx="25" ry="10" fill="#438f9e"/><rect x="-11" y="-22" width="22" height="23" rx="6" fill="${options.efficient?'#8eb7a0':'#e8bd76'}"/><path d="M-29,-12 h58" stroke="#6b7f7d" stroke-width="7" stroke-linecap="round"/>${options.aerator?[[-19,-25],[-2,-36],[19,-27],[9,-18]].map(([x,y],i)=>`<circle data-fish-bubble="${i}" cx="${x}" cy="${y}" r="${3+i%2}" stroke="#e8fff4" fill="#c2eee5" opacity=".8"/>`).join(''):''}</g>${options.biofilter?`<g data-fish-filter="owned" data-fish-object="water" transform="translate(${loc(6.3,2.7).x} ${loc(6.3,2.7).y})"><rect x="-15" y="-26" width="30" height="27" rx="5" fill="#527f6b" stroke="#355d51" stroke-width="2"/><path d="M-8,-18h16m-16,7h16" stroke="#cfdfbc" stroke-width="3"/><path d="M0,1v12h-24" fill="none" stroke="#698d82" stroke-width="5"/></g>`:''}<g data-fish-object="feed" transform="translate(${loc(5.8,1).x} ${loc(5.8,1).y})"><path d="M-15,-30 q15,-8 30,0 l5,30 q-20,12 -40,0Z" fill="#e6c485" stroke="#9c855a" stroke-width="2"/><path d="M-14,-27 h28" stroke="#937c53" stroke-width="3"/><ellipse cy="-12" rx="8" ry="5" fill="#839e76"/>${options.autoFeeder?'<circle data-fish-feeder="on" cx="18" cy="-29" r="7" fill="#528675" stroke="#def0ce" stroke-width="2"/>':''}</g><g data-fish-object="market" transform="translate(${loc(6.2,5.7).x} ${loc(6.2,5.7).y})"><path d="M0,5 v-42" stroke="#9d855d" stroke-width="5"/><rect x="-21" y="-43" width="42" height="24" rx="5" fill="#f0dfae" stroke="#a28a5c" stroke-width="2"/><path d="M-10,-30 h20 m-7,-6 7,6 -7,6" stroke="#61856d" stroke-width="3" fill="none"/></g><path d="M${loc(5.5,5.5).x},${loc(5.5,5.5).y} l20,-45 m-5,0 a15,8 0 1,0 -30,0 a15,8 0 1,0 30,0" stroke="#78948c" fill="none" stroke-width="3" pointer-events="none"/></svg>`;
}

/** @param {number} [rotation] */
export const fishPondPreview=(rotation=0)=>fishPondScene(rotation);
